def _school(u):
    pos = [(0, 40, 80), (70, 10, 70), (95, 62, 76), (160, 30, 84), (205, 66, 68)]
    fs = "".join(_fish(f"{u}s{k}", "#37627f", "#a9c3d2", "#eef3f6", "#cfe0ea").replace("<svg ", f'<svg x="{x}" y="{y}" width="{w}" height="{w*.78:.0f}" ', 1)
                 for k, (x, y, w) in enumerate(pos))
    return f'<svg viewBox="0 0 290 120">{fs}</svg>'

# builder, top %, cross time s, width % of scene, motion, depth (1 near .. .5 far), moves right?
ANIMALS = [
    (lambda u: _fish(u, "#ff6a00", "#ff8d26", "#ffb25c", "#ff7a10", stripes=True), 62, 18, 9, "swim", 1.0, 0),
    (lambda u: _fish(u, "#ffcf10", "#ffe04a", "#fff0a0", "#ffd21f", tall=1.45), 38, 22, 10, "swim", 1.0, 1),
    (_school, 22, 26, 20, "swim", .8, 0),
    (lambda u: _jelly(u, "#f6a8ff", "#8a5cff"), 26, 0, 7, "float", .95, 0),
    (_turtle, 52, 36, 17, "swim", 1.0, 1),
    (lambda u: _fish(u, "#1c4668", "#7fa6c0", "#e8f0f4", "#d9b53c"), 42, 15, 16, "swim", 1.0, 0),
    (_octopus, 60, 0, 10, "float", .95, 0),
    (_manta, 12, 40, 22, "swim", .85, 1),
    (lambda u: _torp(u, "#6c8ea3", "#dfe9ef", "dolphin"), 30, 24, 26, "swim", .9, 0),
    (lambda u: _jelly(u, "#7fe3ff", "#2a7bff"), 46, 0, 6, "float", .7, 0),
    (lambda u: _torp(u, "#56707f", "#e6edf1", "shark"), 54, 30, 30, "swim", .75, 1),
    (lambda u: _torp(u, "#2f4d66", "#a9bccb", "whale"), 8, 58, 42, "swim", .6, 0),
]

def ocean_scene(pct):
    n = round(pct / 100 * len(ANIMALS))
    h = '<div class="scene"><div class="sand"></div>' + "".join(
        f'<div class="kelp" style="left:{x}%;height:{ht}px;animation-delay:-{x%5}s"></div>' for x, ht in [(5, 90), (9, 64), (88, 80), (94, 100)])
    h += "".join(f'<div class="bub" style="left:{(i*53)%95}%;animation-delay:{i*.9}s;width:{6+i%4*3}px;height:{6+i%4*3}px"></div>' for i in range(8))
    for i, (fn, top, dur, w, mo, dp, fl) in enumerate(ANIMALS[:n]):
        if mo == "swim":
            pos = f"animation:{'swimR' if fl else 'swim'} {dur}s linear -{i*4.7:.1f}s infinite,fadein 1.4s ease;"
            bz = f"animation:bobY {4+i%3}s ease-in-out -{i}s infinite alternate;"
        else:
            pos, bz = f"left:{15 + (i*37) % 65}%;", f"animation:drift {6+i%3}s ease-in-out -{i}s infinite alternate;"
        look = f"opacity:{.45+.55*dp:.2f};filter:blur({(1-dp)*1.6:.1f}px) saturate({.7+.3*dp:.2f}) drop-shadow(0 8px 8px rgba(0,15,35,.35));"
        h += (f'<div class="an" style="top:{top}%;width:{w}%;min-width:34px;{pos}"><div style="{bz}{look}">'
              f'<div style="{"transform:scaleX(-1)" if fl else ""}">{fn(f"a{i}")}</div></div></div>')
    if n == 0:
        h += '<p style="position:absolute;inset:0;display:grid;place-items:center;opacity:.8;margin:0">🌊 The ocean is quiet... log some water to bring it to life!</p>'
    return h + f'<div style="position:absolute;left:14px;bottom:8px;font-size:.8rem;opacity:.85">🐠 {n} / {len(ANIMALS)} sea friends awake</div></div>'
# ==== CREATURES END ====

# ======================= REALISTIC LAYERED OCEAN =======================
# All image layers (water, reef pieces, turtle, jellyfish, fish) are embedded below as _OC_DATA, so this single file is the whole app.
# If they were ever removed, the app quietly falls back to the older ocean_scene() above.
OC_CSS = """
.oc{position:relative;width:100%;aspect-ratio:3/2;border-radius:24px;overflow:hidden;border:1px solid rgba(255,255,255,.25);margin:10px 0;background:#06324f;box-shadow:0 8px 32px rgba(0,0,0,.35)}
.oc .o,.oc .cr{position:absolute;pointer-events:none}.oc .o{background-size:100% 100%;background-repeat:no-repeat}
.oc .cr div{width:100%;height:100%}.oc .cr i{display:block;width:100%;height:100%;background-size:100% 100%;background-repeat:no-repeat}
.oc{contain:layout paint}.oc .cr>div,.oc .rays{will-change:transform}
.oc .grow{animation:oc-grow 2.4s ease-out both;transform-origin:50% 100%}
@keyframes oc-grow{from{opacity:0;transform:translateY(5%) scale(.97)}to{opacity:1}}
@keyframes oc-fx{from{transform:translateX(var(--a))}to{transform:translateX(var(--b))}}
@keyframes oc-bob{from{transform:translateY(-7%)}to{transform:translateY(7%)}}
@keyframes oc-jd{from{transform:translateY(0)}to{transform:translateY(-8%)}}
@keyframes oc-pulse{0%,100%{transform:scale(1,1)}50%{transform:scale(1.04,.93)}}
@keyframes oc-sway{from{transform:translateX(-4%) skewX(-3deg)}to{transform:translateX(4%) skewX(3deg)}}
@keyframes oc-rise{to{transform:translateY(-480px)}}
.oc .rays{position:absolute;inset:-12% -12% 25% -12%;background:repeating-linear-gradient(103deg,transparent 0 5%,rgba(200,245,255,.13) 7.5%,transparent 10.5%);animation:oc-sway 18s ease-in-out infinite alternate;pointer-events:none}
.oc .vig{position:absolute;inset:0;box-shadow:inset 0 0 90px rgba(0,25,55,.6);pointer-events:none}
.oc .pl{position:absolute;bottom:-2%;width:3px;height:3px;border-radius:50%;background:rgba(220,250,255,.7);animation:oc-rise 14s linear infinite;opacity:.6}
.oc .cap{position:absolute;left:14px;bottom:10px;font-size:.78rem;color:#dff3ff;text-shadow:0 1px 3px rgba(0,0,0,.7)}
.oc.done{box-shadow:0 0 30px rgba(120,220,255,.45)}
"""

_OC_DATA = {
    "water": "",
    "reef_far": "",
    "reef_left": "",
    "reef_mid": "",
    "reef_right": "",
    "jelly_small": "",
    "jelly_big": "",
    "turtle": "",
    "fish_a": "",
    "fish_b": "",
}
_OC_LAYOUT = {"reef_far":{"l":0.0,"t":42.522,"w":100.0,"h":33.259},"reef_left":{"l":0.0,"t":53.683,"w":56.473,"h":46.317},"reef_mid":{"l":32.812,"t":67.076,"w":43.006,"h":32.924},"reef_right":{"l":49.182,"t":53.683,"w":50.818,"h":46.317},"jelly_small":{"l":40.848,"t":20.201,"w":7.44,"h":13.281},"jelly_big":{"l":77.53,"t":16.741,"w":14.807,"h":30.246},"turtle":{"l":24.182,"t":35.379,"w":16.295,"h":10.826},"fish_a":{"l":7.961,"t":38.728,"w":3.869,"h":4.018},"fish_b":{"l":2.679,"t":35.491,"w":4.167,"h":4.018}}

@st.cache_resource
def _ocean_assets():
    """Returns (css, layout) for the embedded image layers."""
    try:
        css = ["<style>"] + [f".im-{k}{{background-image:url(data:image/webp;base64,{v})}}" for k, v in _OC_DATA.items()]
        return "\n".join(css) + OC_CSS + "</style>", _OC_LAYOUT
    except Exception:
        return "", {}

# (name, top %, seconds to cross, direction 0 = swims right / 1 = swims left, size)
_FISH = [("fish_a", 38, 26, 0, 1.7), ("fish_b", 43, 32, 1, 1.9), ("fish_a", 35, 29, 0, 1.5),
         ("fish_b", 46, 37, 1, 2.1), ("fish_a", 41, 33, 0, 1.8), ("fish_b", 33, 41, 1, 1.6)]
_STAGES = [(8, "reef", "reef_far"), (12, "fish", 0), (15, "fish", 1), (18, "fish", 2), (25, "reef", "reef_left"),
           (33, "jelly", "jelly_small"), (38, "fish", 3), (43, "reef", "reef_mid"), (52, "turtle", "turtle"),
           (58, "fish", 4), (62, "reef", "reef_right"), (70, "fish", 5), (80, "jelly", "jelly_big")]

def ocean_scene_real(pct):
    """A reef that starts dormant and comes alive as water is logged: coral, plants, fish, jellyfish and a sea turtle."""
    L = _ocean_assets()[1]
    act = [s for s in _STAGES if pct >= s[0]]
    prev = S.get("oc_prev", 0); S.oc_prev = len(act)          # only the newest additions play their "grow in" animation
    g = lambda i: " grow" if i >= prev else ""
    box = lambda k, m=1.0: f"left:{L[k]['l']}%;top:{L[k]['t']}%;width:{L[k]['w']*m:.2f}%;height:{L[k]['h']*m:.2f}%"
    h = f'<div class="oc{" done" if pct >= 100 else ""}"><div class="o im-water" style="left:0;top:0;width:100%;height:100%"></div>'
    for i, (thr, kind, nm) in enumerate(act):
        if kind == "reef": h += f'<div class="o im-{nm}{g(i)}" style="{box(nm)}"></div>'
    h += f'<div class="rays" style="opacity:{.35 + .65 * min(pct, 100) / 100:.2f}"></div>'
    for i, (thr, kind, nm) in enumerate(act):
        if kind == "fish":
            name, top, dur, d, k = _FISH[nm]; w, hh = L[name]["w"] * k, L[name]["h"] * k; span = 100 / w * 100
            a, b = (-130, span + 30) if d == 0 else (span + 30, -130)
            h += (f'<div class="cr{g(i)}" style="left:0;top:{top}%;width:{w:.2f}%;height:{hh:.2f}%"><div style="animation:oc-fx {dur}s linear -{nm * 9}s infinite;--a:{a:.0f}%;--b:{b:.0f}%">'
                  f'<div style="animation:oc-bob {2 + nm * .3:.1f}s ease-in-out infinite alternate"><i class="im-{name}" style="{"transform:scaleX(-1)" if d else ""}"></i></div></div></div>')
        elif kind == "turtle":
            w, hh = L[nm]["w"] * 1.1, L[nm]["h"] * 1.1; span = 100 / w * 100
            h += (f'<div class="cr{g(i)}" style="left:0;top:30%;width:{w:.2f}%;height:{hh:.2f}%"><div style="animation:oc-fx 85s linear -30s infinite;--a:-120%;--b:{span + 20:.0f}%">'
                  f'<div style="animation:oc-bob 6s ease-in-out infinite alternate"><i class="im-{nm}"></i></div></div></div>')
        elif kind == "jelly":
            h += (f'<div class="cr{g(i)}" style="{box(nm)}"><div style="animation:oc-jd {6 + len(nm) % 3}s ease-in-out infinite alternate">'
                  f'<i class="im-{nm}" style="transform-origin:50% 20%;animation:oc-pulse 3.4s ease-in-out infinite"></i></div></div>')
    h += "".join(f'<span class="pl" style="left:{(i * 37) % 97}%;animation-duration:{11 + i % 5 * 3}s;animation-delay:-{i * 1.7:.1f}s"></span>' for i in range(8 + int(14 * min(pct, 100) / 100)))
    return h + f'<div class="vig"></div><div class="cap">Ocean life: {len(act)} / {len(_STAGES)}</div></div>'
