    now_name = next((n for n, v in presets.items() if v == current), "Custom")
    pick = st.radio(label, names, index=names.index(now_name), horizontal=True, key=key + "_pick")
    if pick == "Custom":
        return int(st.number_input("How many minutes?", 1, 480, int(current), 1, key=key + "_min"))
    return presets[pick]

