# Drinks you can log: (emoji, share of the volume that counts toward your water goal).
# These shares are rough, illustrative values - edit them freely.
BEVERAGES = {
    "Water": ("💧", 1.00),
    "Tea": ("🍵", 0.90),
    "Coffee": ("☕", 0.85),
    "Iced tea": ("🧊", 0.85),
    "Juice": ("🧃", 0.85),
    "Smoothie": ("🥤", 0.80),
    "Coconut water": ("🥥", 0.95),
    "Lemon water": ("🍋", 0.95),
    "Milk": ("🥛", 0.90),
}

def add_drink(name, ml):
    """Log a drink; only the hydrating share of it counts toward the goal."""
    emoji, share = BEVERAGES[name]
    credit = round(ml * share)
    S.total += credit
    S.log.append((f"{emoji} {name} {ml} ml", credit))
    S.last = time.time(); S.snooze_until = 0.0; S.tip = random.choice(TIPS)

def _undo_last():
    if S.log: S.total = max(S.total - S.log.pop()[1], 0)
def _reset_day():
    S.total, S.log, S.last, S.celebrated, S.snooze_until = 0, [], time.time(), False, 0.0
def _test_reminder_now():
    S.last = time.time() - S.remind_min * 60 - 1; S.snooze_until = 0.0

